"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[99717],{99717:function(t){t.exports=JSON.parse('{"content":"\\n\\n<center>\\n<RestaurantCard\\n          cover=\\"/assets/snippets/location/0755208f2a50987665d76afeec96d136.jpg\\"\\n          title=\\"아저씨커피\\"\\n          cuisine=\\"카페\\"\\n          address=\\"충청남도 공주시 먹자1길 1\\"\\n          rating=4.0\\n          tags=\\"cafe\\"\\n        />\\n</center>\\n\\n## Review\\n\\n점심 식사를 마치고 근처를 산책하던 중, 딱 봐도 커피가 맛있어 보이는 곳이 눈에 띄어 <mark>테이크아웃</mark>을 하려고 들르게 되었다.  \\n\\n안 그래도 공주에서 가볼 만한 좋은 카페를 찾아볼 때 봐두었던 후보 리스트 중 하나였어서 망설임 없이 바로 들어갔다.  \\n\\n카페 내부 자리는 상당히 협소한 편이었지만, 애초에 테이크아웃을 할 생각이었기 때문에 큰 문제는 되지 않았다.  \\n\\n카운터에서 주문을 마치고 기다리는 동안 잠시 내부를 둘러보았는데, 공간이 아기자기하고 예쁘게 잘 꾸며져 있었다.  \\n```adcard\\n```\\n여담으로 당시 카페에 얼음이 다 떨어졌었는지, 따님으로 보이는 직원분이 바로 앞 편의점으로 가셔서 얼음을 급히 사 오시기도 했다.  \\n\\n얼마 지나지 않아 주문한 커피가 금방 나왔는데 맛이 상당히 풍부했다.  \\n특히 진하게 맴도는 <mark>커피 향</mark>이 딱 내 스타일이었다.  \\n\\n만약 내부에 자리가 있고 시간도 여유로웠다면 매장 안에서 느긋하게 시간을 보내며 즐겼어도 참 좋았을 것 같다.  \\n다음에 공주를 다시 방문하게 된다면 꼭 한 번 더 들러보고 싶은 그런 카페다.\\n## Pictures\\n<pictures>\\n<img src=\\"/assets/snippets/location/0755208f2a50987665d76afeec96d136.jpg\\" style=\\"max-width: 100%; height: auto; object-fit: contain;\\" alt=\\"아저씨커피\\">\\n<img src=\\"/assets/snippets/location/849e02a105d453aaae68d62accef6822.jpg\\" style=\\"max-width: 100%; height: auto; object-fit: contain;\\" alt=\\"아저씨커피\\">\\n<img src=\\"/assets/snippets/location/a2dbb775b5ec893b5615bc3680d31fde.jpg\\" style=\\"max-width: 100%; height: auto; object-fit: contain;\\" alt=\\"아저씨커피\\">\\n<img src=\\"/assets/snippets/location/e2c97a399bb1e80c692754e635cf1a32.jpg\\" style=\\"max-width: 100%; height: auto; object-fit: contain;\\" alt=\\"아저씨커피\\">\\n<img src=\\"/assets/snippets/location/51d181068a3ff949f5da42e1fb995680.jpg\\" style=\\"max-width: 100%; height: auto; object-fit: contain;\\" alt=\\"아저씨커피\\">\\n<img src=\\"/assets/snippets/location/c4039dab3ac7d9134f5cffc1b8c60162.jpg\\" style=\\"max-width: 100%; height: auto; object-fit: contain;\\" alt=\\"아저씨커피\\">\\n</pictures>\\n"}')}}]);